<?php
declare(strict_types=1);
require __DIR__ . '/_lib.php';

function cti_vendor_store(): string {
    $dir=cti_runtime_dir().'/cms'; if(!is_dir($dir)&&!mkdir($dir,0700,true)&&!is_dir($dir))cti_json(503,['ok'=>false,'error'=>'cms_storage_unavailable']);
    $path=$dir.'/vendors.json'; if(!is_file($path))file_put_contents($path,json_encode(['schema'=>'cti.vendors.v2','updatedAt'=>gmdate('c'),'vendors'=>[]],JSON_PRETTY_PRINT),LOCK_EX); return $path;
}
function cti_vendor_load(): array{$d=json_decode((string)file_get_contents(cti_vendor_store()),true);return is_array($d)?$d:['schema'=>'cti.vendors.v2','updatedAt'=>gmdate('c'),'vendors'=>[]];}
function cti_vendor_auth(): void{$e=trim((string)getenv('CTI_CMS_ADMIN_TOKEN'));$a=trim((string)($_SERVER['HTTP_AUTHORIZATION']??''));if($e===''||!hash_equals('Bearer '.$e,$a))cti_json(401,['ok'=>false,'error'=>'cms_auth_required']);}
function cti_vendor_list(mixed $v,int $max=160):array{if(!is_array($v))return[];return array_values(array_filter(array_map(fn($x)=>cti_clean_scalar($x,$max),$v)));}
